        let a = analyze(agg, zy, aggBs, loadPPI(m.tid), m.tid, m.home, m.away, leagueName(m));
        /* 自我纠错功能已按用户要求下线（浏览器端纠偏样本永远<10，原逻辑本就是空转） */
        ensureFused(a, m, agg, aggBs);        // 直播场次也挂三段融合面板（轻量直连）
