      + '<td style="padding:7px 6px;white-space:nowrap"><a onclick="__tfToggle('+ci+');event.stopPropagation()" style="cursor:pointer;color:var(--acc)">对照卡</a>'+(r.tid?' <span style="opacity:.35">|</span> <a'+tidAttr+'>明细</a>':'')+'</td>'
