  const _plainGuide = '<div style="background:linear-gradient(135deg,#0e2a1c,#0e1f2a);border:1px solid #1f6b46;border-radius:12px;padding:12px 14px;margin:8px 0;font-size:12.5px;line-height:1.75;color:#dcefe2">'
