  const hardAct = hard.filter(x=>x.ph !== 'fin'), hardFin = hard.filter(x=>x.ph === 'fin');
  const planAct = plan.filter(x=>x.ph !== 'fin'), planFin = plan.filter(x=>x.ph === 'fin');
