      w.innerHTML = _RV_HEAD + renderRows(d) + '</tbody></table>';
      try { console.log('[perf] 复盘展开第 ' + _di + ' 天：' + Math.round(((window.performance&&performance.now)?performance.now():Date.now()) - _t0) + 'ms'); } catch(e){}
