  const TIER7 = { strong: '破蛋·强 (p≥0.85)', mid: '破蛋·中性 (p 0.70~0.85)', weak: '破蛋·偏弱 (p 0.65~0.70)', low: '破蛋·弱 (p<0.65)' };
  const _all = (RD.statRows||[]);
